VALUES ('doc-09-mitre-attack-p0-18488', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-26T19:54:24.583Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[QUADAGENT](https://attack.mitre.org/software/S0269) stores a session identifier unique to the compromised system as well as a pre-shared key used for encrypting and decrypting C2 communications within a Registry key (such as `HKCU\\Office365DCOMCheck`) in the `HKCU` hive.(Citation: Unit 42 QUADAGENT July 2018)", "external_references": [{"description": "Lee, B., Falcone, R. (2018, July 25). OilRig Targets Technology Service Provider and Government Agency with QUADAGENT. Retrieved August 9, 2018.", "source_name": "Unit 42 QUADAGENT July 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/07/unit42-oilrig-targets-technology-service-provider-government-agency-quadagent/"}], "id": "relationship--91aa29c1-28a9-414a-aa3c-a6293b8d078f", "modified": "2026-04-29T14:23:06.124Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7e6c2a9d-9dc1-4eb0-b27c-91e8076a9d77", "spec_version": "2.1", "target_ref": "attack-pattern--02c5abff-30bf-4703-ab92-1f6072fae939", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18488', 0, 99, '09-mitre-attack', 'retrieved', '7935750E844A49C94B3D0C685B3E8E0E284DFFCDDAA2703467D2B68167373A17', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
