VALUES ('doc-09-mitre-attack-p0-18510', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-03-15T15:47:19.534Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Sagerunex](https://attack.mitre.org/software/S1210) gathers host information and stages it locally as a RAR file prior to exfiltration.(Citation: Cisco LotusBlossom 2025) [Sagerunex](https://attack.mitre.org/software/S1210) stores logged data in an encrypted file located at `%TEMP%/TS_FB56.tmp` during execution.(Citation: Symantec Bilbug 2022)", "external_references": [{"description": "Joey Chen, Cisco Talos. (2025, February 27). Lotus Blossom espionage group targets multiple industries with different versions of Sagerunex and hacking tools. Retrieved March 15, 2025.", "source_name": "Cisco LotusBlossom 2025", "url": "https://blog.talosintelligence.com/lotus-blossom-espionage-group/"}, {"description": "Symntec Threat Hunter Team. (2022, November 12). Billbug: State-sponsored Actor Targets Cert Authority, Government Agencies in Multiple Asian Countries. Retrieved March 15, 2025.", "source_name": "Symantec Bilbug 2022", "url": "https://www.security.com/threat-intelligence/espionage-asia-governments-cert-authority"}], "id": "relationship--c66dddb1-0003-4af8-9887-5642964e0fd0", "modified": "2026-04-29T14:23:06.197Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7f269253-c225-45ff-87c2-5e8ef6dd369f", "spec_version": "2.1", "target_ref": "attack-pattern--1c34f7aa-9341-4a48-bfab-af22e51aca6c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18510', 0, 127, '09-mitre-attack', 'retrieved', '3DCA8D024E9FD47ACA105CA718AB7881DBF67F351B8EB5E0573980A4C0568E45', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
