VALUES ('doc-09-mitre-attack-p0-18536', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-21T21:14:33.093Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LP-Notes](https://attack.mitre.org/software/S9036) has used the `ImpersonateLoggedOnUser` API to impersonate the security context of the taskhostw.exe process.(Citation: ESET_MuddyWater_Dec2025) Additionally, [LP-Notes](https://attack.mitre.org/software/S9036) has also used the `CredUIPromptForWindowsCredentialsW` API to obtain Windows credentials.(Citation: ESET_MuddyWater_Dec2025)", "external_references": [{"description": "ESET Research. (2025, December 2). MuddyWater: Snakes by the riverbank. Retrieved February 17, 2026.", "source_name": "ESET_MuddyWater_Dec2025", "url": "https://www.welivesecurity.com/en/eset-research/muddywater-snakes-riverbank/"}], "id": "relationship--226fb240-24c2-4eb6-ac1b-c9c60712371c", "modified": "2026-04-29T14:23:05.952Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--7fbf1f1e-cbd8-4060-8e3b-7ca0e56ce3fe", "spec_version": "2.1", "target_ref": "attack-pattern--391d824f-0ef1-47a0-b0ee-c59a75e27670", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18536', 0, 78, '09-mitre-attack', 'retrieved', 'E381FD89C4F6942524B329CB1677B967F711BD0F30D2820760EBD09DCB81885D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
