VALUES ('doc-09-mitre-attack-p0-18582', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-10T18:28:31.212Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GlassWorm](https://attack.mitre.org/software/S9010) has established persistence on macOS via a LaunchAgent by writing a plist under `/library/LaunchAgents`.(Citation: Koi Glassworm New Tricks December 2025)(Citation: Socket GlassWorm January 2026)", "external_references": [{"description": "Gal Hachamov. (2025, December 29). GlassWorm Goes Mac: Fresh Infrastructure, New Tricks. Retrieved April 10, 2026.", "source_name": "Koi Glassworm New Tricks December 2025", "url": "https://www.koi.ai/blog/glassworm-goes-mac-fresh-infrastructure-new-tricks"}, {"description": "Kirill Boychenko. (2026, January 31). GlassWorm Loader Hits Open VSX via Developer Account Compromise. Retrieved April 10, 2026.", "source_name": "Socket GlassWorm January 2026", "url": "https://socket.dev/blog/glassworm-loader-hits-open-vsx-via-suspected-developer-account-compromise"}], "id": "relationship--22234127-7175-4ace-a2eb-535849e81f8d", "modified": "2026-04-29T14:23:05.952Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--809bc57b-4d4c-43de-b698-448334ed8185", "spec_version": "2.1", "target_ref": "attack-pattern--d10cbd34-42e3-45c0-84d2-535a09849584", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18582', 0, 107, '09-mitre-attack', 'retrieved', 'B4B7F69D5E594FFCCF53E72DA9FB0EDE7FC5E5C26823550CC3AEA0CFCED05693', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
