VALUES ('doc-09-mitre-attack-p0-18583', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-10T19:26:44.559Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GlassWorm](https://attack.mitre.org/software/S9010) has leveraged peer-to-peer software to facilitate communications within the victim network to include the software WebRTC.(Citation: Koi Glassworm InvisibleCode October 2025) [GlassWorm](https://attack.mitre.org/software/S9010) has also established a SOCKS proxy to interact with victim devices that also acted as a proxy node for follow-on behaviors.(Citation: Koi Glassworm InvisibleCode October 2025)", "external_references": [{"description": "Idan Dardikman. (2025, October 18). GlassWorm: First Self-Propagating Worm Using Invisible Code Hits OpenVSX Marketplace. Retrieved April 10, 2026.", "source_name": "Koi Glassworm InvisibleCode October 2025", "url": "https://www.koi.ai/blog/glassworm-first-self-propagating-worm-using-invisible-code-hits-openvsx-marketplace"}], "id": "relationship--29184298-9a17-4def-8ad8-10381b4bde89", "modified": "2026-04-29T14:23:05.961Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--809bc57b-4d4c-43de-b698-448334ed8185", "spec_version": "2.1", "target_ref": "attack-pattern--f6dacc85-b37d-458e-b58d-74fc4bbf5755", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18583', 0, 107, '09-mitre-attack', 'retrieved', '2D46E3B4A494236E7517987AFD534B7E4062DA3672E1D7CB0FC1AD73BF9792AF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
