VALUES ('doc-09-mitre-attack-p0-18588', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-10T19:20:11.386Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GlassWorm](https://attack.mitre.org/software/S9010) has harvested Safari cookies stored within `/Library/Containers/com.apple.Safari/Data/Library/Cookies/ Cookies.binarycookies`.(Citation: Socket GlassWorm January 2026) [GlassWorm](https://attack.mitre.org/software/S9010) has also stolen cookies within Chromium and Firefox browsers.(Citation: Koi Glassworm New Tricks December 2025)(Citation: Socket GlassWorm January 2026)", "external_references": [{"description": "Gal Hachamov. (2025, December 29). GlassWorm Goes Mac: Fresh Infrastructure, New Tricks. Retrieved April 10, 2026.", "source_name": "Koi Glassworm New Tricks December 2025", "url": "https://www.koi.ai/blog/glassworm-goes-mac-fresh-infrastructure-new-tricks"}, {"description": "Kirill Boychenko. (2026, January 31). GlassWorm Loader Hits Open VSX via Developer Account Compromise. Retrieved April 10, 2026.", "source_name": "Socket GlassWorm January 2026", "url": "https://socket.dev/blog/glassworm-loader-hits-open-vsx-via-suspected-developer-account-compromise"}], "id": "relationship--42d78c28-8a26-4cac-88bb-93e35d5226e4", "modified": "2026-04-29T14:23:06.016Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--809bc57b-4d4c-43de-b698-448334ed8185", "spec_version": "2.1", "target_ref": "attack-pattern--10ffac09-e42d-4f56-ab20-db94c67d76ff", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18588', 0, 115, '09-mitre-attack', 'retrieved', '5A765AF10D2EB7C1A5285A99BFF4B7952CDC7FFAEF9029BB3674B05A577308F0', 'v1', '{"source_id": "09-mitre-attack", "version": "