VALUES ('doc-09-mitre-attack-p0-18589', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-10T18:35:49.516Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GlassWorm](https://attack.mitre.org/software/S9010) has leveraged blockchain-based C2 infrastructure to include Solana blockchain that contains additional C2 details within the memo field.(Citation: Koi Glassworm New Tricks December 2025)(Citation: Koi Glassworm Extensions November 2025)(Citation: Koi Glassworm InvisibleCode October 2025)(Citation: Aikido GlassWorm October 2025)(Citation: Socket GlassWorm January 2026)(Citation: Koi GlassWorm Rust December 2025) [GlassWorm](https://attack.mitre.org/software/S9010) has also leveraged Google Calendar to host encoded data.(Citation: Koi Glassworm InvisibleCode October 2025)(Citation: Socket GlassWorm January 2026)(Citation: Koi GlassWorm Rust December 2025)", "external_references": [{"description": "Gal Hachamov. (2025, December 29). GlassWorm Goes Mac: Fresh Infrastructure, New Tricks. Retrieved April 10, 2026.", "source_name": "Koi Glassworm New Tricks December 2025", "url": "https://www.koi.ai/blog/glassworm-goes-mac-fresh-infrastructure-new-tricks"}, {"description": "Idan Dardikman, Yuval Ronen, Lotan Sery. (2025, November 6). GlassWorm Returns: New Wave Strikes as We Expose Attacker Infrastructure. Retrieved April 10, 2026.", "source_name": "Koi Glassworm Extensions November 2025", "url": "https://www.koi.ai/blog/glassworm-returns-new-wave-openvsx-malware-expose-attacker-infrastructure"}, {"description": "Idan Dardikman. (2025, October 18). GlassWorm: First Self-Propagating Worm Using Invisible Code Hits OpenVSX Marketplace. Retrieved April 10, 2026.", "source_name": "Koi Glassworm InvisibleCode October 2025", "url": "https://www.koi.ai/blog/glassworm-first-self-propagating-worm-using-invisible-code-hits-openvsx-marketplace"}, {"description": "Ilyas Makari. (2025, October 31). The Return of the Invisible Threat: Hidden PUA Unicode Hits GitHub repositorties. Retrieved April 10, 2026.", "source_name": "Aikido GlassWorm October 2025", "url": "https://www.aikido.dev/blog/the-return-of-the-invisible-threat-hidden-pua-unicode-hits-github-repositorties"}, {"description": "Kirill Boychenko. (2026, January 31). GlassWorm Loader Hits Open VSX via Developer Account Compromise. Retrieved April 10, 2026.", "source_name": "Socket GlassWorm January 2026", "url": "https://socket.dev/blog/glassworm-loader-hits-open-vsx-via-suspected-developer-account-compromise"}, {"description": "Lotan Sery. (2025, December 10). GlassWorm Goes Native: Same Infrastructure, Hardened Delivery. Retrieved April 10, 2026.", "source_name": "Koi GlassWorm Rust December 2025", "url": "https://www.koi.ai/blog/glassworm-goes-native-same-infrastructure-hardened-delivery"}], "id": "relationship--44d29b3e-75ee-48b8-977c-5e231c49e84a", "modified": "2026-04-29T14:23:06.019Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--809bc57b-4d4c-43de-b698-448334ed8185", "spec_version": "2.1", "target_ref": "attack-pattern--f7827069-0bf2-4764-af4f-23fae0d181b7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18589', 0, 268, '09-mitre-attack', 'retrieved', 'ED7CFE8D52EB5D0FA478A8867CA8DB8D4F692F84973159A0DF8008617485D3F9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
