VALUES ('doc-09-mitre-attack-p0-18602', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-10T19:31:29.587Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GlassWorm](https://attack.mitre.org/software/S9010) has leveraged geofencing logic to detect whether it is operating in a Russian associated time zone to determine whether it continues to execute.(Citation: Socket GlassWorm January 2026)", "external_references": [{"description": "Kirill Boychenko. (2026, January 31). GlassWorm Loader Hits Open VSX via Developer Account Compromise. Retrieved April 10, 2026.", "source_name": "Socket GlassWorm January 2026", "url": "https://socket.dev/blog/glassworm-loader-hits-open-vsx-via-suspected-developer-account-compromise"}], "id": "relationship--9d4c9cb8-d5fb-4679-8b38-fab55f237963", "modified": "2026-04-29T14:23:06.139Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--809bc57b-4d4c-43de-b698-448334ed8185", "spec_version": "2.1", "target_ref": "attack-pattern--c877e33f-1df6-40d6-b1e7-ce70f16f4979", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18602', 0, 84, '09-mitre-attack', 'retrieved', 'E44727E1D7B2D76634C76CF6BB8BBCF2D0E8EDDBDB5576820736A8D0429962AE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
