VALUES ('doc-09-mitre-attack-p0-18603', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-10T19:03:21.369Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[GlassWorm](https://attack.mitre.org/software/S9010) has utilized AppleScript to include `set keychainPassword to do shell script` to execute shell command that retrieves passwords from the macOS keychain.(Citation: Koi Glassworm New Tricks December 2025)", "external_references": [{"description": "Gal Hachamov. (2025, December 29). GlassWorm Goes Mac: Fresh Infrastructure, New Tricks. Retrieved April 10, 2026.", "source_name": "Koi Glassworm New Tricks December 2025", "url": "https://www.koi.ai/blog/glassworm-goes-mac-fresh-infrastructure-new-tricks"}], "id": "relationship--9f2a884d-0974-4080-80a1-13a29a7f25c7", "modified": "2026-04-29T14:23:06.142Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--809bc57b-4d4c-43de-b698-448334ed8185", "spec_version": "2.1", "target_ref": "attack-pattern--37b11151-1776-4f8f-b328-30939fbf2ceb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18603', 0, 85, '09-mitre-attack', 'retrieved', '05D07FECBC0F8A0DF7B90154CFC7A0C4E352F3C482D14CACD949B756A9BFF033', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
