VALUES ('doc-09-mitre-attack-p0-18631', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-06-22T20:48:11.495Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Uroburos](https://attack.mitre.org/software/S0022) has the ability to gather basic system information and run the POSIX API `gethostbyname`.(Citation: Joint Cybersecurity Advisory AA23-129A Snake Malware May 2023)", "external_references": [{"description": "FBI et al. (2023, May 9). Hunting Russian Intelligence “Snake” Malware. Retrieved June 8, 2023.", "source_name": "Joint Cybersecurity Advisory AA23-129A Snake Malware May 2023", "url": "https://www.cisa.gov/sites/default/files/2023-05/aa23-129a_snake_malware_2.pdf"}], "id": "relationship--a0e4dc2c-1977-4c4c-a5ee-4710fb3ef1a5", "modified": "2026-04-29T14:23:06.144Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--80a014ba-3fef-4768-990b-37d8bd10d7f4", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18631', 0, 80, '09-mitre-attack', 'retrieved', 'EBFEBDE2F900505DF1999A36BC808B9D9FBE80CBAC5364C629110491CDD368ED', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
