VALUES ('doc-09-mitre-attack-p0-18632', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-06-22T19:51:48.793Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Individual [Uroburos](https://attack.mitre.org/software/S0022) implants can use multiple communication channels based on one of four available modes of operation.(Citation: Joint Cybersecurity Advisory AA23-129A Snake Malware May 2023)", "external_references": [{"description": "FBI et al. (2023, May 9). Hunting Russian Intelligence “Snake” Malware. Retrieved June 8, 2023.", "source_name": "Joint Cybersecurity Advisory AA23-129A Snake Malware May 2023", "url": "https://www.cisa.gov/sites/default/files/2023-05/aa23-129a_snake_malware_2.pdf"}], "id": "relationship--a2006705-7f1b-4081-a074-5313f1d8c7af", "modified": "2026-04-29T14:23:06.145Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--80a014ba-3fef-4768-990b-37d8bd10d7f4", "spec_version": "2.1", "target_ref": "attack-pattern--84e02621-8fdf-470f-bd58-993bb6a89d91", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18632', 0, 82, '09-mitre-attack', 'retrieved', '1FAB7244DE7F416C90C4261B65D4A319CD98EB95DA5BA8B18EEB94198D9D93FC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
