VALUES ('doc-09-mitre-attack-p0-18641', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-06-23T20:15:12.020Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Uroburos](https://attack.mitre.org/software/S0022) can use its `Process List` command to enumerate processes on compromised hosts.(Citation: Joint Cybersecurity Advisory AA23-129A Snake Malware May 2023)", "external_references": [{"description": "FBI et al. (2023, May 9). Hunting Russian Intelligence “Snake” Malware. Retrieved June 8, 2023.", "source_name": "Joint Cybersecurity Advisory AA23-129A Snake Malware May 2023", "url": "https://www.cisa.gov/sites/default/files/2023-05/aa23-129a_snake_malware_2.pdf"}], "id": "relationship--db75183b-9ad3-41e4-9730-f0bba5ef55c1", "modified": "2026-04-29T14:23:06.225Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--80a014ba-3fef-4768-990b-37d8bd10d7f4", "spec_version": "2.1", "target_ref": "attack-pattern--8f4a33ec-8b1f-4b80-a2f6-642b2e479580", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18641', 0, 78, '09-mitre-attack', 'retrieved', 'E0D9AC2230A7F2FF1D8077AC701F5F1DEBD363F802D89D53383FC232131050AD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
