VALUES ('doc-09-mitre-attack-p0-18648', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-22T20:34:05.418Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Metamorfo](https://attack.mitre.org/software/S0455) includes payloads written in JavaScript.(Citation: Medium Metamorfo Apr 2020) ", "external_references": [{"description": "Erlich, C. (2020, April 3). The Avast Abuser: Metamorfo Banking Malware Hides By Abusing Avast Executable. Retrieved May 26, 2020.", "source_name": "Medium Metamorfo Apr 2020", "url": "https://medium.com/@chenerlich/the-avast-abuser-metamorfo-banking-malware-hides-by-abusing-avast-executable-ac9b8b392767"}], "id": "relationship--07f72efd-7960-4530-92f3-6ced33087212", "modified": "2026-04-29T14:23:05.914Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--81c57a96-fc8c-4f91-af8e-63e24c2927c2", "spec_version": "2.1", "target_ref": "attack-pattern--0f4a0c76-ab2d-4cb0-85d3-3f0efb8cba0d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18648', 0, 69, '09-mitre-attack', 'retrieved', 'DDAD2944B11A85F8A4E7F0BEBA0FB4B03C44705778908C61C7C944A0DA7B82B5', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
