VALUES ('doc-09-mitre-attack-p0-18649', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-21T17:01:35.599Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Metamorfo](https://attack.mitre.org/software/S0455) has searched the compromised system for banking applications.(Citation: FireEye Metamorfo Apr 2018)(Citation: ESET Casbaneiro Oct 2019)", "external_references": [{"description": "Sierra, E., Iglesias, G.. (2018, April 24). Metamorfo Campaigns Targeting Brazilian Users. Retrieved July 30, 2020.", "source_name": "FireEye Metamorfo Apr 2018", "url": "https://www.fireeye.com/blog/threat-research/2018/04/metamorfo-campaign-targeting-brazilian-users.html"}, {"description": "ESET Research. (2019, October 3). Casbaneiro: peculiarities of this banking Trojan that affects Brazil and Mexico. Retrieved September 23, 2021.", "source_name": "ESET Casbaneiro Oct 2019", "url": "https://www.welivesecurity.com/2019/10/03/casbaneiro-trojan-dangerous-cooking/"}], "id": "relationship--082b64f6-cc70-4bc8-a49f-bf0f125883f7", "modified": "2026-04-29T14:23:05.914Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--81c57a96-fc8c-4f91-af8e-63e24c2927c2", "spec_version": "2.1", "target_ref": "attack-pattern--e3b6daca-e963-4a69-aee6-ed4fd653ad58", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18649', 0, 99, '09-mitre-attack', 'retrieved', 'D8F390C1F5F0A8CDEE7BB54356D91459A3E21C776E6B5E1D92661C066093D059', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
