VALUES ('doc-09-mitre-attack-p0-18702', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-06-18T20:14:36.648Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Upon execution [Spica](https://attack.mitre.org/software/S1140) can decode an embedded .pdf and write it to the desktop as a decoy document.(Citation: Google TAG COLDRIVER January 2024)", "external_references": [{"description": "Shields, W. (2024, January 18). Russian threat group COLDRIVER expands its targeting of Western officials to include the use of malware. Retrieved June 13, 2024.", "source_name": "Google TAG COLDRIVER January 2024", "url": "https://blog.google/threat-analysis-group/google-tag-coldriver-russian-phishing-malware/"}], "id": "relationship--e7c81430-1c3a-4ee8-9f10-4a3fcad2da54", "modified": "2026-04-29T14:23:06.240Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--824a230d-0f6a-4fd0-99df-8d464db2265e", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18702', 0, 87, '09-mitre-attack', 'retrieved', 'E35EC6402EF1BA755C62FD19495138009BD4D2094EEFDD6808343EA41B8AF51D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
