VALUES ('doc-09-mitre-attack-p0-18704', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-20T12:07:56.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Embargo](https://attack.mitre.org/software/S1247) has utilized a hardcoded mutex name of “LoadUpOnGunsBringYourFriends” using the `CreateMutexW()` function.(Citation: Cyble Embargo Ransomware May 2024) [Embargo](https://attack.mitre.org/software/S1247) has also utilized a hardcoded mutex name of “IntoTheFloodAgainSameOldTrip.\"(Citation: ESET Embargo Ransomware October 2024)", "external_references": [{"description": "Cyble. (2024, May 24). The Rust Revolution: New Embargo Ransomware Steps In. Retrieved October 19, 2025.", "source_name": "Cyble Embargo Ransomware May 2024", "url": "https://cyble.com/blog/the-rust-revolution-new-embargo-ransomware-steps-in/"}, {"description": "Jan Holman, Tomas Zvara. (2024, October 23). Embargo ransomware: Rock’n’Rust. Retrieved October 19, 2025.", "source_name": "ESET Embargo Ransomware October 2024", "url": "https://www.welivesecurity.com/en/eset-research/embargo-ransomware-rocknrust/"}], "id": "relationship--0cc89d3e-9fe9-42f1-acb5-a7bce55840c0", "modified": "2026-04-29T14:23:05.920Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--82adb90e-43b8-4bce-9efe-afeba65457b2", "spec_version": "2.1", "target_ref": "attack-pattern--49fca0d2-685d-41eb-8bd4-05451cc3a742", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18704', 0, 111, '09-mitre-attack', 'retrieved', '1B30253A5347E61524D4B98BE9F502F3BC4EEBA740E4BDD5A44F73AB400A2537', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
