VALUES ('doc-09-mitre-attack-p0-18705', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-20T11:40:33.121Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Embargo](https://attack.mitre.org/software/S1247) has leveraged MS4Killer to deliver a vulnerable driver to the victim device, sometimes referred to as Bring Your Own Vulnerable Driver (BYOVD).(Citation: ESET Embargo Ransomware October 2024) [Embargo](https://attack.mitre.org/software/S1247) has utilized the vulnerable driver probmon.sys version 3.0.0.4 which had a revoked certificated from “ITM System Co.,LTD.”(Citation: ESET Embargo Ransomware October 2024)", "external_references": [{"description": "Jan Holman, Tomas Zvara. (2024, October 23). Embargo ransomware: Rock’n’Rust. Retrieved October 19, 2025.", "source_name": "ESET Embargo Ransomware October 2024", "url": "https://www.welivesecurity.com/en/eset-research/embargo-ransomware-rocknrust/"}], "id": "relationship--0cdabb4e-45d7-4307-818e-0647c08a8b45", "modified": "2026-04-29T14:23:05.921Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--82adb90e-43b8-4bce-9efe-afeba65457b2", "spec_version": "2.1", "target_ref": "attack-pattern--b21c3b2d-02e6-45b1-980b-e69051040839", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18705', 0, 104, '09-mitre-attack', 'retrieved', '7BECAC8F707C0E22D6E101540C4022F069499CC54FCC20B9F53CC8CE556CDE61', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
