VALUES ('doc-09-mitre-attack-p0-18713', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-20T12:19:10.650Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Embargo](https://attack.mitre.org/software/S1247) has avoided encrypting specific files and directories by leveraging a regular expression within the ransomware binary.(Citation: Cyble Embargo Ransomware May 2024)", "external_references": [{"description": "Cyble. (2024, May 24). The Rust Revolution: New Embargo Ransomware Steps In. Retrieved October 19, 2025.", "source_name": "Cyble Embargo Ransomware May 2024", "url": "https://cyble.com/blog/the-rust-revolution-new-embargo-ransomware-steps-in/"}], "id": "relationship--7d2cff9e-7017-415d-a8e2-1ed543e521f8", "modified": "2026-04-29T14:23:06.097Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--82adb90e-43b8-4bce-9efe-afeba65457b2", "spec_version": "2.1", "target_ref": "attack-pattern--9b00925a-7c4b-4e53-bfc8-9a6a806fde03", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18713', 0, 77, '09-mitre-attack', 'retrieved', '9AA835117838CF0DF15634FAAED81A3AEF46C3055B868E5ACA934D797EBBB291', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
