VALUES ('doc-09-mitre-attack-p0-18721', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-20T11:59:38.752Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Embargo](https://attack.mitre.org/software/S1247) has modified the Windows Registry to start a custom service named irnagentd in Safe Mode.(Citation: ESET Embargo Ransomware October 2024)", "external_references": [{"description": "Jan Holman, Tomas Zvara. (2024, October 23). Embargo ransomware: Rock’n’Rust. Retrieved October 19, 2025.", "source_name": "ESET Embargo Ransomware October 2024", "url": "https://www.welivesecurity.com/en/eset-research/embargo-ransomware-rocknrust/"}], "id": "relationship--be24db0e-1ae0-4478-9b83-7d40d0f0a1c0", "modified": "2026-04-29T14:23:06.185Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--82adb90e-43b8-4bce-9efe-afeba65457b2", "spec_version": "2.1", "target_ref": "attack-pattern--9efb1ea7-c37b-4595-9640-b7680cd84279", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18721', 0, 74, '09-mitre-attack', 'retrieved', '8832B7BBB7240A7FFDE3BC442E5A304860E939ABF7A0A2582B68F26D6F353918', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
