VALUES ('doc-09-mitre-attack-p0-18722', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-20T12:02:30.330Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Embargo](https://attack.mitre.org/software/S1247) has created a service named irnagentd that executed the MDeployer loader after the system is rebooted in Safe Mode.(Citation: ESET Embargo Ransomware October 2024)", "external_references": [{"description": "Jan Holman, Tomas Zvara. (2024, October 23). Embargo ransomware: Rock’n’Rust. Retrieved October 19, 2025.", "source_name": "ESET Embargo Ransomware October 2024", "url": "https://www.welivesecurity.com/en/eset-research/embargo-ransomware-rocknrust/"}], "id": "relationship--e63477f0-9081-4633-a375-8cb72320f4ad", "modified": "2026-04-29T14:23:06.238Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--82adb90e-43b8-4bce-9efe-afeba65457b2", "spec_version": "2.1", "target_ref": "attack-pattern--f1951e8a-500e-4a26-8803-76d95c4554b4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18722', 0, 78, '09-mitre-attack', 'retrieved', '8052C1F42EDC2AB1DCE23F3BC44E529AEDE7DE155C87EEC8046D8CDDFDC45F2A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
