VALUES ('doc-09-mitre-attack-p0-18723', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-10-20T11:32:33.850Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Embargo](https://attack.mitre.org/software/S1247) has the ability to encrypt files with the ChaCha20 and Curve25519 cryptographic algorithms.(Citation: Cyble Embargo Ransomware May 2024) [Embargo](https://attack.mitre.org/software/S1247) also has the ability to encrypt system data and add a random six-letter extension consisting of hexadecimal characters such as \".b58eeb\" or “.3d828a” to encrypted files.(Citation: ESET Embargo Ransomware October 2024) ", "external_references": [{"description": "Cyble. (2024, May 24). The Rust Revolution: New Embargo Ransomware Steps In. Retrieved October 19, 2025.", "source_name": "Cyble Embargo Ransomware May 2024", "url": "https://cyble.com/blog/the-rust-revolution-new-embargo-ransomware-steps-in/"}, {"description": "Jan Holman, Tomas Zvara. (2024, October 23). Embargo ransomware: Rock’n’Rust. Retrieved October 19, 2025.", "source_name": "ESET Embargo Ransomware October 2024", "url": "https://www.welivesecurity.com/en/eset-research/embargo-ransomware-rocknrust/"}], "id": "relationship--eb5164e4-bd62-4b9d-bfcc-fba023b7e235", "modified": "2026-04-29T14:23:06.245Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--82adb90e-43b8-4bce-9efe-afeba65457b2", "spec_version": "2.1", "target_ref": "attack-pattern--b80d107d-fa0d-4b60-9684-b0433e8bdba0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18723', 0, 130, '09-mitre-attack', 'retrieved', '1D95BE6C02FC67BCD1CC6E9A5611C900B5CFD3ED71823FB0D34D6DE8F1B0949B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corp