VALUES ('doc-09-mitre-attack-p0-18793', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-24T14:07:40.526Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PipeMon](https://attack.mitre.org/software/S0501) can check for the presence of ESET and Kaspersky security software.(Citation: ESET PipeMon May 2020)", "external_references": [{"description": "Tartare, M. et al. (2020, May 21). No “Game over” for the Winnti Group. Retrieved August 24, 2020.", "source_name": "ESET PipeMon May 2020", "url": "https://www.welivesecurity.com/2020/05/21/no-game-over-winnti-group/"}], "id": "relationship--f3afa419-b741-4a1c-bb4d-569cde6ab558", "modified": "2026-04-29T14:23:06.256Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8393dac0-0583-456a-9372-fd81691bca20", "spec_version": "2.1", "target_ref": "attack-pattern--cba37adb-d6fb-4610-b069-dd04c0643384", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18793', 0, 72, '09-mitre-attack', 'retrieved', 'AAD28B861B8256E3E27A01396EB555FBF830AEABDFF693F2CD42FABC0FB14235', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
