VALUES ('doc-09-mitre-attack-p0-18794', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-08-24T13:40:23.150Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[PipeMon](https://attack.mitre.org/software/S0501) has used call to LoadLibrary to load its installer. [PipeMon](https://attack.mitre.org/software/S0501) loads its modules using reflective loading or custom shellcode.(Citation: ESET PipeMon May 2020)", "external_references": [{"description": "Tartare, M. et al. (2020, May 21). No “Game over” for the Winnti Group. Retrieved August 24, 2020.", "source_name": "ESET PipeMon May 2020", "url": "https://www.welivesecurity.com/2020/05/21/no-game-over-winnti-group/"}], "id": "relationship--f77738b8-e17c-4b6b-98fc-ffcc569cc008", "modified": "2026-04-29T14:23:06.261Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8393dac0-0583-456a-9372-fd81691bca20", "spec_version": "2.1", "target_ref": "attack-pattern--0a5231ec-41af-4a35-83d0-6bdf11f28c65", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18794', 0, 80, '09-mitre-attack', 'retrieved', 'D66AA177965E8D8270AE2FED6EC1F9D9F88DF8B8D955DBA2DC917502B0C3B506', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
