VALUES ('doc-09-mitre-attack-p0-18795', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-21T14:15:47.374Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SYNful Knock](https://attack.mitre.org/software/S0519) is malware that is inserted into a network device by patching the operating system image.(Citation: Mandiant - Synful Knock)(Citation: Cisco Synful Knock Evolution)", "external_references": [{"description": "Bill Hau, Tony Lee, Josh Homan. (2015, September 15). SYNful Knock - A Cisco router implant - Part I. Retrieved November 17, 2024.", "source_name": "Mandiant - Synful Knock", "url": "https://cloud.google.com/blog/topics/threat-intelligence/synful-knock-acis/"}, {"description": "Graham Holmes. (2015, October 8). Evolution of attacks on Cisco IOS devices. Retrieved October 19, 2020.", "source_name": "Cisco Synful Knock Evolution", "url": "https://blogs.cisco.com/security/evolution-of-attacks-on-cisco-ios-devices"}], "id": "relationship--1fbc7b2a-1cdb-455b-bd5a-b0ff29efe800", "modified": "2026-04-29T14:23:05.948Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--84c1ecc6-e5a2-4e8a-bf4b-651a618e0053", "spec_version": "2.1", "target_ref": "attack-pattern--d245808a-7086-4310-984a-a84aaaa43f8f", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18795', 0, 110, '09-mitre-attack', 'retrieved', '5961F3FF262E21FF713D10D5842599C3F6CD997B364B0CB860CA2BA23367987A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
