VALUES ('doc-09-mitre-attack-p0-18796', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-10-21T14:15:47.328Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[SYNful Knock](https://attack.mitre.org/software/S0519) can be sent instructions via special packets to change its functionality. Code for new functionality can be included in these messages.(Citation: Mandiant - Synful Knock)", "external_references": [{"description": "Bill Hau, Tony Lee, Josh Homan. (2015, September 15). SYNful Knock - A Cisco router implant - Part I. Retrieved November 17, 2024.", "source_name": "Mandiant - Synful Knock", "url": "https://cloud.google.com/blog/topics/threat-intelligence/synful-knock-acis/"}], "id": "relationship--5d9b14c3-70ea-46b3-9b0d-1595c215efec", "modified": "2026-04-29T14:23:06.053Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--84c1ecc6-e5a2-4e8a-bf4b-651a618e0053", "spec_version": "2.1", "target_ref": "attack-pattern--451a9977-d255-43c9-b431-66de80130c8c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18796', 0, 88, '09-mitre-attack', 'retrieved', '030C34A639924AB24F6D1E2F55A0D9328EE4CD1811BE7D405A4D29DC7CA7EA74', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
