VALUES ('doc-09-mitre-attack-p0-18815', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-04-28T18:12:13.518Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[KONNI](https://attack.mitre.org/software/S0356) has used certutil to download and decode base64 encoded strings and has also devoted a custom section to performing all the components of the deobfuscation process.(Citation: Medium KONNI Jan 2020)(Citation: Malwarebytes Konni Aug 2021)", "external_references": [{"description": "Karmi, D. (2020, January 4). A Look Into Konni 2019 Campaign. Retrieved April 28, 2020.", "source_name": "Medium KONNI Jan 2020", "url": "https://medium.com/d-hunter/a-look-into-konni-2019-campaign-b45a0f321e9b"}, {"description": "Threat Intelligence Team. (2021, August 23). New variant of Konni malware used in campaign targetting Russia. Retrieved January 5, 2022.", "source_name": "Malwarebytes Konni Aug 2021", "url": "https://blog.malwarebytes.com/threat-intelligence/2021/08/new-variant-of-konni-malware-used-in-campaign-targetting-russia/"}], "id": "relationship--06f8a778-eebf-4d73-86d3-6ebdbf94ce46", "modified": "2026-04-29T14:23:05.913Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--86b92f6c-9c05-4c51-b361-4c7bb13e21a1", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18815', 0, 116, '09-mitre-attack', 'retrieved', '265E5FBAEF3FB5C0FCED758B37BA1B7AE6525932107EF1823A265FB2351A1380', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
