VALUES ('doc-09-mitre-attack-p0-18861', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[T9000](https://attack.mitre.org/software/S0098) performs checks for various antivirus and security products during installation.(Citation: Palo Alto T9000 Feb 2016)", "external_references": [{"description": "Grunzweig, J. and Miller-Osborn, J.. (2016, February 4). T9000: Advanced Modular Backdoor Uses Complex Anti-Analysis Techniques. Retrieved April 15, 2016.", "source_name": "Palo Alto T9000 Feb 2016", "url": "http://researchcenter.paloaltonetworks.com/2016/02/t9000-advanced-modular-backdoor-uses-complex-anti-analysis-techniques/"}], "id": "relationship--74e84133-f84a-469a-bfd7-1a514af2f15e", "modified": "2026-04-29T14:23:06.085Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--876f6a77-fbc5-4e13-ab1a-5611986730a3", "spec_version": "2.1", "target_ref": "attack-pattern--cba37adb-d6fb-4610-b069-dd04c0643384", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18861', 0, 75, '09-mitre-attack', 'retrieved', '5D09CCEF842A6E842D23D8AE92ACF0D0F9375CFA62A61C5845F58397D349E561', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
