VALUES ('doc-09-mitre-attack-p0-18862', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[T9000](https://attack.mitre.org/software/S0098) uses the Skype API to record audio and video calls. It writes encrypted data to %APPDATA%\\Intel\\Skype .(Citation: Palo Alto T9000 Feb 2016)", "external_references": [{"description": "Grunzweig, J. and Miller-Osborn, J.. (2016, February 4). T9000: Advanced Modular Backdoor Uses Complex Anti-Analysis Techniques. Retrieved April 15, 2016.", "source_name": "Palo Alto T9000 Feb 2016", "url": "http://researchcenter.paloaltonetworks.com/2016/02/t9000-advanced-modular-backdoor-uses-complex-anti-analysis-techniques/"}], "id": "relationship--842f8f4b-9d90-4533-850f-777f33ef8257", "modified": "2026-04-29T14:23:06.106Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--876f6a77-fbc5-4e13-ab1a-5611986730a3", "spec_version": "2.1", "target_ref": "attack-pattern--1035cdf2-3e5f-446f-a7a7-e8f6d7925967", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18862', 0, 82, '09-mitre-attack', 'retrieved', 'D37DF7CCD2C503F72B595ADAB490CE3659CEC69E6BDEA9B57CF1CBD5788C5E8B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
