VALUES ('doc-09-mitre-attack-p0-18868', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-04-30T16:48:25.687Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Winnti for Linux](https://attack.mitre.org/software/S0430) has used HTTP in outbound communications.(Citation: Chronicle Winnti for Linux May 2019)", "external_references": [{"description": "Chronicle Blog. (2019, May 15). Winnti: More than just Windows and Gates. Retrieved April 29, 2020.", "source_name": "Chronicle Winnti for Linux May 2019", "url": "https://medium.com/chronicle-blog/winnti-more-than-just-windows-and-gates-e4f03436031a"}], "id": "relationship--2fc3c031-8a39-4bc9-b3e1-4c5f6ac1e292", "modified": "2026-04-29T14:23:05.974Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8787e86d-8475-4f13-acea-d33eb83b6105", "spec_version": "2.1", "target_ref": "attack-pattern--df8b2a25-8bdf-4856-953c-a04372b1c161", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18868', 0, 71, '09-mitre-attack', 'retrieved', '96A6814780E87F7F49850F7D9FF20EA65EE116E790F2146E7B091339E5A7A4A8', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
