VALUES ('doc-09-mitre-attack-p0-18870', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-04-30T15:51:59.690Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Winnti for Linux](https://attack.mitre.org/software/S0430) has decoded XOR encoded strings holding its configuration upon execution.(Citation: Chronicle Winnti for Linux May 2019)", "external_references": [{"description": "Chronicle Blog. (2019, May 15). Winnti: More than just Windows and Gates. Retrieved April 29, 2020.", "source_name": "Chronicle Winnti for Linux May 2019", "url": "https://medium.com/chronicle-blog/winnti-more-than-just-windows-and-gates-e4f03436031a"}], "id": "relationship--45e9de66-7203-48e9-bd9b-096c289f35db", "modified": "2026-04-29T14:23:06.021Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8787e86d-8475-4f13-acea-d33eb83b6105", "spec_version": "2.1", "target_ref": "attack-pattern--3ccef7ae-cb5e-48f6-8302-897105fbf55c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18870', 0, 75, '09-mitre-attack', 'retrieved', 'A524372D1DCEF9691E6188CE515413D748D681C875EB2BA904F57375758AE078', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
