VALUES ('doc-09-mitre-attack-p0-18877', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-04-17T16:14:26.510Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RAPIDPULSE](https://attack.mitre.org/software/S1113) retrieves files from the victim system via encrypted commands sent to the web shell.(Citation: Mandiant Pulse Secure Update May 2021)", "external_references": [{"description": "Perez, D. et al. (2021, May 27). Re-Checking Your Pulse: Updates on Chinese APT Actors Compromising Pulse Secure VPN Devices. Retrieved February 5, 2024.", "source_name": "Mandiant Pulse Secure Update May 2021", "url": "https://www.mandiant.com/resources/blog/updates-on-chinese-apt-compromising-pulse-secure-vpn-devices"}], "id": "relationship--32447230-f703-4baf-bd01-1477f7142f00", "modified": "2026-04-29T14:23:05.984Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--880f7b3e-ad27-4158-8b03-d44c9357950b", "spec_version": "2.1", "target_ref": "attack-pattern--3c4a2599-71ee-4405-ba1e-0e28414b4bc5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18877', 0, 85, '09-mitre-attack', 'retrieved', 'AED938183FDCF6B7E668363D249FC20AF1B54528A7CFE2B2BB61DB640D3D7CB6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
