VALUES ('doc-09-mitre-attack-p0-18878', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-02-13T17:53:37.006Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RAPIDPULSE](https://attack.mitre.org/software/S1113) is a web shell that is capable of arbitrary file read on targeted web servers to exfiltrate items of interest on the victim device.(Citation: Mandiant Pulse Secure Update May 2021)", "external_references": [{"description": "Perez, D. et al. (2021, May 27). Re-Checking Your Pulse: Updates on Chinese APT Actors Compromising Pulse Secure VPN Devices. Retrieved February 5, 2024.", "source_name": "Mandiant Pulse Secure Update May 2021", "url": "https://www.mandiant.com/resources/blog/updates-on-chinese-apt-compromising-pulse-secure-vpn-devices"}], "id": "relationship--95373c46-d959-465a-9ac1-d1d5271805f2", "modified": "2026-04-29T14:23:06.128Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--880f7b3e-ad27-4158-8b03-d44c9357950b", "spec_version": "2.1", "target_ref": "attack-pattern--5d0d3609-d06d-49e1-b9c9-b544e0c618cb", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18878', 0, 95, '09-mitre-attack', 'retrieved', '6BD1DAC9A26054B00BDAB3BB569226C144C792109FC041DD60E021E11BE3B30E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
