VALUES ('doc-09-mitre-attack-p0-18903', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-07-15T19:28:00.683Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[gh0st RAT](https://attack.mitre.org/software/S0032) has encrypted TCP communications to evade detection.(Citation: Gh0stRAT ATT March 2019)", "external_references": [{"description": "Quinn, J. (2019, March 25). The odd case of a Gh0stRAT variant. Retrieved July 15, 2020.", "source_name": "Gh0stRAT ATT March 2019", "url": "https://cybersecurity.att.com/blogs/labs-research/the-odd-case-of-a-gh0strat-variant"}], "id": "relationship--cc2de45c-a1f3-4085-ac35-dffa8a86e9b3", "modified": "2026-04-29T14:23:06.204Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--88c621a7-aef9-4ae0-94e3-1fc87123eb24", "spec_version": "2.1", "target_ref": "attack-pattern--b8902400-e6c5-4ba2-95aa-2d35b442b118", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18903', 0, 67, '09-mitre-attack', 'retrieved', '5C8DA8E8727CF59C99C6597C0FC35A719F79677B4DDEB23EA24B30BE438C55FD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
