VALUES ('doc-09-mitre-attack-p0-18950', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[JHUHUGIT](https://attack.mitre.org/software/S0044) has registered itself as a scheduled task to run each time the current user logs in.(Citation: ESET Sednit Part 1)(Citation: ESET Sednit July 2015)", "external_references": [{"description": "ESET. (2016, October). En Route with Sednit - Part 1: Approaching the Target. Retrieved November 8, 2016.", "source_name": "ESET Sednit Part 1", "url": "http://www.welivesecurity.com/wp-content/uploads/2016/10/eset-sednit-part1.pdf"}, {"description": "ESET Research. (2015, July 10). Sednit APT Group Meets Hacking Team. Retrieved March 1, 2017.", "source_name": "ESET Sednit July 2015", "url": "http://www.welivesecurity.com/2015/07/10/sednit-apt-group-meets-hacking-team/"}], "id": "relationship--1aa10371-6473-416a-8b8b-17c36f700233", "modified": "2026-04-29T14:23:05.941Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8ae43c46-57ef-47d5-a77a-eebb35628db2", "spec_version": "2.1", "target_ref": "attack-pattern--005a06c6-14bf-4118-afa0-ebcd8aebb0c9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18950', 0, 103, '09-mitre-attack', 'retrieved', '1D1A6405FDEBA6D0ED2B341E74CC27EABCD6FB49B9C871FDA9A2A0E4A9EA39A3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
