VALUES ('doc-09-mitre-attack-p0-18962', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[JHUHUGIT](https://attack.mitre.org/software/S0044) can retrieve an additional payload from its C2 server.(Citation: ESET Sednit Part 1)(Citation: Unit 42 Sofacy Feb 2018) [JHUHUGIT](https://attack.mitre.org/software/S0044) has a command to download files to the victim’s machine.(Citation: Talos Seduploader Oct 2017)", "external_references": [{"description": "ESET. (2016, October). En Route with Sednit - Part 1: Approaching the Target. Retrieved November 8, 2016.", "source_name": "ESET Sednit Part 1", "url": "http://www.welivesecurity.com/wp-content/uploads/2016/10/eset-sednit-part1.pdf"}, {"description": "Lee, B, et al. (2018, February 28). Sofacy Attacks Multiple Government Entities. Retrieved March 15, 2018.", "source_name": "Unit 42 Sofacy Feb 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/02/unit42-sofacy-attacks-multiple-government-entities/"}, {"description": "Mercer, W., et al. (2017, October 22). \"Cyber Conflict\" Decoy Document Used in Real Cyber Conflict. Retrieved November 2, 2018.", "source_name": "Talos Seduploader Oct 2017", "url": "https://blog.talosintelligence.com/2017/10/cyber-conflict-decoy-document.html"}], "id": "relationship--f39d9e4d-b4f9-4c12-aa8e-a44f8550b57f", "modified": "2026-04-29T14:23:06.256Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8ae43c46-57ef-47d5-a77a-eebb35628db2", "spec_version": "2.1", "target_ref": "attack-pattern--e6919abc-99f9-4c6c-95a5-14761e7b2add", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18962', 0, 142, '09-mitre-attack', 'retrieved', '1DCE9827E3BC379A9CC059622060019C928E8AD1ECE9C36780D28764DEA885AC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
