VALUES ('doc-09-mitre-attack-p0-18963', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "A [JHUHUGIT](https://attack.mitre.org/software/S0044) variant takes screenshots by simulating the user pressing the \"Take Screenshot\" key (VK_SCREENSHOT), accessing the screenshot saved in the clipboard, and converting it to a JPG image.(Citation: Unit 42 Playbook Dec 2017)(Citation: Talos Seduploader Oct 2017)", "external_references": [{"description": "Mercer, W., et al. (2017, October 22). \"Cyber Conflict\" Decoy Document Used in Real Cyber Conflict. Retrieved November 2, 2018.", "source_name": "Talos Seduploader Oct 2017", "url": "https://blog.talosintelligence.com/2017/10/cyber-conflict-decoy-document.html"}, {"description": "Unit 42. (2017, December 15). Unit 42 Playbook Viewer. Retrieved December 20, 2017.", "source_name": "Unit 42 Playbook Dec 2017", "url": "https://web.archive.org/web/20230702043312/https://pan-unit42.github.io/playbook_viewer/"}], "id": "relationship--073215cd-bc1e-48e8-8f3a-7d24f18b32c6", "modified": "2026-06-13T12:07:50.831Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8ae43c46-57ef-47d5-a77a-eebb35628db2", "spec_version": "2.1", "target_ref": "attack-pattern--0259baeb-9f63-4c69-bf10-eb038c390688", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-18963', 0, 118, '09-mitre-attack', 'retrieved', '7E211443BADE6BE07F40BE0B3E8B0117DFE7958BD1F2BDBEC825528FD3270C40', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
