VALUES ('doc-09-mitre-attack-p0-19038', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-01-29T21:47:53.704Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Micropsia](https://attack.mitre.org/software/S0339) gathers the hostname and OS version from the victim’s machine.(Citation: Talos Micropsia June 2017)(Citation: Radware Micropsia July 2018)", "external_references": [{"description": "Rascagneres, P., Mercer, W. (2017, June 19). Delphi Used To Score Against Palestine. Retrieved November 13, 2018.", "source_name": "Talos Micropsia June 2017", "url": "https://blog.talosintelligence.com/2017/06/palestine-delphi.html"}, {"description": "Tsarfaty, Y. (2018, July 25). Micropsia Malware. Retrieved November 13, 2018.", "source_name": "Radware Micropsia July 2018", "url": "https://www.radware.com/blog/security/2018/07/micropsia-malware/"}], "id": "relationship--002c9202-d7a0-4181-b912-42f7d6d38339", "modified": "2026-04-29T14:23:05.903Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8c050cea-86e1-4b63-bf21-7af4fa483349", "spec_version": "2.1", "target_ref": "attack-pattern--354a7f88-63fb-41b5-a801-ce3b377b36f1", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19038', 0, 93, '09-mitre-attack', 'retrieved', '313043C822CBAF8E6157DDE8A06E0003B394B1F5146B55CE59476B1551AEEA91', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
