VALUES ('doc-09-mitre-attack-p0-19064', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-02T13:57:47.561Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Kerrdown](https://attack.mitre.org/software/S0585) has gained execution through victims opening malicious links.(Citation: Amnesty Intl. Ocean Lotus February 2021)", "external_references": [{"description": "Amnesty International. (2021, February 24). Vietnamese activists targeted by notorious hacking group. Retrieved March 1, 2021.", "source_name": "Amnesty Intl. Ocean Lotus February 2021", "url": "https://www.amnestyusa.org/wp-content/uploads/2021/02/Click-and-Bait_Vietnamese-Human-Rights-Defenders-Targeted-with-Spyware-Attacks.pdf"}], "id": "relationship--e733d4b5-0881-4de8-9461-58ca239b7c82", "modified": "2026-04-29T14:23:06.240Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8c1d01ff-fdc0-4586-99bd-c248e0761af5", "spec_version": "2.1", "target_ref": "attack-pattern--ef67e13e-5598-4adc-bdb2-998225874fa9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19064', 0, 71, '09-mitre-attack', 'retrieved', '8D7B63C0764BCD31CEEE82AE2F2EDEC963813ADFB916EB7E5526D1B8FCDDC12A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
