VALUES ('doc-09-mitre-attack-p0-19069', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-17T16:28:34.672Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedLine Stealer](https://attack.mitre.org/software/S1240) has used both valid certificates and self-signed digital certificates to appear legitimate.(Citation: ESET RedLine Stealer November 2024)", "external_references": [{"description": "Alexandre Cote Cyr. (2024, November 8). Life on a crooked RedLine: Analyzing the infamous infostealer’s backend. Retrieved September 17, 2025.", "source_name": "ESET RedLine Stealer November 2024", "url": "https://www.welivesecurity.com/en/eset-research/life-crooked-redline-analyzing-infamous-infostealers-backend/"}], "id": "relationship--02595a79-3ef9-41a6-be6f-14aebf3a96f1", "modified": "2026-04-29T14:23:05.906Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8c8e8b01-b4b1-479b-a7a9-78c40a12b916", "spec_version": "2.1", "target_ref": "attack-pattern--32901740-b42c-4fdd-bc02-345b5dc57082", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19069', 0, 78, '09-mitre-attack', 'retrieved', '6A8FCC6AD9BBD6EDCC6DF623CD7913F80ECB50CEE21F745171C1973BF9BD6B76', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
