VALUES ('doc-09-mitre-attack-p0-19070', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-17T16:42:37.114Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedLine Stealer](https://attack.mitre.org/software/S1240) can disable security software and update services.(Citation: Splunk RedLine Stealer June 2023)", "external_references": [{"description": "Splunk Threat Research Team. (2023, June 1). Do Not Cross The ''RedLine'' Stealer: Detections and Analysis. Retrieved September 17, 2025.", "source_name": "Splunk RedLine Stealer June 2023", "url": "https://www.splunk.com/en_us/blog/security/do-not-cross-the-redline-stealer-detections-and-analysis.html"}], "id": "relationship--1eb7d0a2-784b-44e8-a1dd-2c444b67bf29", "modified": "2026-04-29T14:23:05.946Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8c8e8b01-b4b1-479b-a7a9-78c40a12b916", "spec_version": "2.1", "target_ref": "attack-pattern--bbde9781-60aa-4b8a-a911-895b0c1b3872", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19070', 0, 73, '09-mitre-attack', 'retrieved', '714F739CE3D6D6FF03CF0AF16DA88187073697CB55DE944ADF30B0679C094FF1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
