VALUES ('doc-09-mitre-attack-p0-19071', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-17T16:35:32.879Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedLine Stealer](https://attack.mitre.org/software/S1240) has obtained the username from the victim’s machine.(Citation: Proofpoint RedLine Stealer March 2020)(Citation: Splunk RedLine Stealer June 2023)(Citation: Veriti RedLine Stealer MAAS April 2023)", "external_references": [{"description": "Proofpoint Threat Insight Team, Jeremy H, Axel F. (2020, March 16). New Redline Password Stealer Malware. Retrieved September 17, 2025.", "source_name": "Proofpoint RedLine Stealer March 2020", "url": "https://www.proofpoint.com/us/blog/threat-insight/new-redline-stealer-distributed-using-coronavirus-themed-email-campaign"}, {"description": "Splunk Threat Research Team. (2023, June 1). Do Not Cross The ''RedLine'' Stealer: Detections and Analysis. Retrieved September 17, 2025.", "source_name": "Splunk RedLine Stealer June 2023", "url": "https://www.splunk.com/en_us/blog/security/do-not-cross-the-redline-stealer-detections-and-analysis.html"}, {"description": "Yair Herling. (2023, April 4). From ChatGPT to RedLine Stealer: The Dark Side of OpenAI and Google Bard. Retrieved September 17, 2025.", "source_name": "Veriti RedLine Stealer MAAS April 2023", "url": "https://veriti.ai/blog/veriti-research/from-chatgpt-to-redline-stealer-the-dark-side-of-openai-and-google-bard/"}], "id": "relationship--242af6ac-a8f9-44fd-ae3f-edd975b37b4c", "modified": "2026-04-29T14:23:05.955Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8c8e8b01-b4b1-479b-a7a9-78c40a12b916", "spec_version": "2.1", "target_ref": "attack-pattern--03d7999c-1f4c-42cc-8373-e7690d318104", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref":