VALUES ('doc-09-mitre-attack-p0-19075', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-17T15:30:08.645Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedLine Stealer](https://attack.mitre.org/software/S1240) malware has been executed through the download of malicious files.(Citation: ESET RedLine Stealer November 2024)(Citation: Kroll RedLine Stealer August 2024)(Citation: Veriti RedLine Stealer MAAS April 2023) [RedLine Stealer](https://attack.mitre.org/software/S1240) has also lured users to install malware with an Install Wizard interface.(Citation: McAfee RedLine Stealer April 2024)", "external_references": [{"description": "Alexandre Cote Cyr. (2024, November 8). Life on a crooked RedLine: Analyzing the infamous infostealer’s backend. Retrieved September 17, 2025.", "source_name": "ESET RedLine Stealer November 2024", "url": "https://www.welivesecurity.com/en/eset-research/life-crooked-redline-analyzing-infamous-infostealers-backend/"}, {"description": "George Glass. (2024, August 14). REDLINESTEALER Malware Driving the Initial Access Broker Market. Retrieved September 17, 2025.", "source_name": "Kroll RedLine Stealer August 2024", "url": "https://www.kroll.com/en/publications/cyber/redlinestealer-malware"}, {"description": "Mohansundaram M, Neil Tyagi. (2024, April 17). Redline Stealer: A Novel Approach. Retrieved September 17, 2025.", "source_name": "McAfee RedLine Stealer April 2024", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/redline-stealer-a-novel-approach/"}, {"description": "Yair Herling. (2023, April 4). From ChatGPT to RedLine Stealer: The Dark Side of OpenAI and Google Bard. Retrieved September 17, 2025.", "source_name": "Veriti RedLine Stealer MAAS April 2023", "url": "https://veriti.ai/blog/veriti-research/from-chatgpt-to-redline-stealer-the-dark-side-of-openai-and-google-bard/"}], "id": "relationship--5a817bea-020f-47f5-8bf3-80e0c8bdef79", "modified": "2026-04-29T14:23:06.049Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8c8e8b01-b4b1-479b-a7a9-78c40a12b916", "spec_version": "2.1", "target_ref": "attack-pattern--232b7f21-adf9-4b42-b936-b9d6f7df856e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19075', 0, 189, '09-mitre-attack', 'retrieved', '70AE25C54237F91920914125B8431EDA61941C2944C84E477BF4ACACFA2E1F3F', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
