VALUES ('doc-09-mitre-attack-p0-19076', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-17T14:58:12.978Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedLine Stealer](https://attack.mitre.org/software/S1240) has collected data from cryptocurrency wallets and harvested credit cards details from browsers.(Citation: ESET RedLine Stealer November 2024)(Citation: Kroll RedLine Stealer August 2024)(Citation: Proofpoint RedLine Stealer March 2020)(Citation: Splunk RedLine Stealer June 2023)(Citation: Veriti RedLine Stealer MAAS April 2023)", "external_references": [{"description": "Alexandre Cote Cyr. (2024, November 8). Life on a crooked RedLine: Analyzing the infamous infostealer’s backend. Retrieved September 17, 2025.", "source_name": "ESET RedLine Stealer November 2024", "url": "https://www.welivesecurity.com/en/eset-research/life-crooked-redline-analyzing-infamous-infostealers-backend/"}, {"description": "George Glass. (2024, August 14). REDLINESTEALER Malware Driving the Initial Access Broker Market. Retrieved September 17, 2025.", "source_name": "Kroll RedLine Stealer August 2024", "url": "https://www.kroll.com/en/publications/cyber/redlinestealer-malware"}, {"description": "Proofpoint Threat Insight Team, Jeremy H, Axel F. (2020, March 16). New Redline Password Stealer Malware. Retrieved September 17, 2025.", "source_name": "Proofpoint RedLine Stealer March 2020", "url": "https://www.proofpoint.com/us/blog/threat-insight/new-redline-stealer-distributed-using-coronavirus-themed-email-campaign"}, {"description": "Splunk Threat Research Team. (2023, June 1). Do Not Cross The ''RedLine'' Stealer: Detections and Analysis. Retrieved September 17, 2025.", "source_name": "Splunk RedLine Stealer June 2023", "url": "https://www.splunk.com/en_us/blog/security/do-not-cross-the-redline-stealer-detections-and-analysis.html"}, {"description": "Yair Herling. (2023, April 4). From ChatGPT to RedLine Stealer: The Dark Side