VALUES ('doc-09-mitre-attack-p0-19078', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-17T14:59:10.550Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedLine Stealer](https://attack.mitre.org/software/S1240) malware has masqueraded as legitimate software such as \"PDF Converter Software\" which has been distributed through poisoned search engine results often resembling legitimate software lures with the combination of typo squatted domains.(Citation: Kroll RedLine Stealer August 2024)", "external_references": [{"description": "George Glass. (2024, August 14). REDLINESTEALER Malware Driving the Initial Access Broker Market. Retrieved September 17, 2025.", "source_name": "Kroll RedLine Stealer August 2024", "url": "https://www.kroll.com/en/publications/cyber/redlinestealer-malware"}], "id": "relationship--5cd22798-0d6e-4bed-b139-c46a4cfa87a5", "modified": "2026-04-29T14:23:06.052Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8c8e8b01-b4b1-479b-a7a9-78c40a12b916", "spec_version": "2.1", "target_ref": "attack-pattern--42e8de7b-37b2-4258-905a-6897815e58e0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19078', 0, 95, '09-mitre-attack', 'retrieved', '94EF995631C0E630BBB90E1F8D599FF5EA87D4205A94ED5443807B4A0165C9BC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
