VALUES ('doc-09-mitre-attack-p0-19079', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-17T16:25:43.378Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedLine Stealer](https://attack.mitre.org/software/S1240) has used obfuscation tools such as DNGuard and Boxed App to pack their code.(Citation: ESET RedLine Stealer November 2024)", "external_references": [{"description": "Alexandre Cote Cyr. (2024, November 8). Life on a crooked RedLine: Analyzing the infamous infostealer’s backend. Retrieved September 17, 2025.", "source_name": "ESET RedLine Stealer November 2024", "url": "https://www.welivesecurity.com/en/eset-research/life-crooked-redline-analyzing-infamous-infostealers-backend/"}], "id": "relationship--5d256f6f-9501-4fec-9255-941b8c2fe35a", "modified": "2026-04-29T14:23:06.052Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8c8e8b01-b4b1-479b-a7a9-78c40a12b916", "spec_version": "2.1", "target_ref": "attack-pattern--deb98323-e13f-4b0c-8d94-175379069062", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19079', 0, 80, '09-mitre-attack', 'retrieved', 'FF46C738E5B95C72E389718DE69538EB59211DBF0FDC2E5AAB166AB23903438D', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
