VALUES ('doc-09-mitre-attack-p0-19080', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-17T14:55:38.675Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedLine Stealer](https://attack.mitre.org/software/S1240) has gathered detailed information about victims’ systems, such as IP addresses, and geolocation.(Citation: ESET RedLine Stealer November 2024)(Citation: Kroll RedLine Stealer August 2024)(Citation: Proofpoint RedLine Stealer March 2020) [RedLine Stealer](https://attack.mitre.org/software/S1240) has also checked the IP from where it was being executed and leveraged an opensource geolocation IP-lookup service. (Citation: McAfee RedLine Stealer April 2024)", "external_references": [{"description": "Alexandre Cote Cyr. (2024, November 8). Life on a crooked RedLine: Analyzing the infamous infostealer’s backend. Retrieved September 17, 2025.", "source_name": "ESET RedLine Stealer November 2024", "url": "https://www.welivesecurity.com/en/eset-research/life-crooked-redline-analyzing-infamous-infostealers-backend/"}, {"description": "George Glass. (2024, August 14). REDLINESTEALER Malware Driving the Initial Access Broker Market. Retrieved September 17, 2025.", "source_name": "Kroll RedLine Stealer August 2024", "url": "https://www.kroll.com/en/publications/cyber/redlinestealer-malware"}, {"description": "Mohansundaram M, Neil Tyagi. (2024, April 17). Redline Stealer: A Novel Approach. Retrieved September 17, 2025.", "source_name": "McAfee RedLine Stealer April 2024", "url": "https://www.mcafee.com/blogs/other-blogs/mcafee-labs/redline-stealer-a-novel-approach/"}, {"description": "Proofpoint Threat Insight Team, Jeremy H, Axel F. (2020, March 16). New Redline Password Stealer Malware. Retrieved September 17, 2025.", "source_name": "Proofpoint RedLine Stealer March 2020", "url": "https://www.proofpoint.com/us/blog/threat-insight/new-redline-stealer-distributed-using-coronavirus-themed-email-campaign"}], "id": "re