VALUES ('doc-09-mitre-attack-p0-19100', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-17T16:44:22.270Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RedLine Stealer](https://attack.mitre.org/software/S1240) has an anti-sandbox technique that requires the malware to consistently check with the C2 server, if the communication fails [RedLine Stealer](https://attack.mitre.org/software/S1240) will not continue execution.(Citation: Splunk RedLine Stealer June 2023)", "external_references": [{"description": "Splunk Threat Research Team. (2023, June 1). Do Not Cross The ''RedLine'' Stealer: Detections and Analysis. Retrieved September 17, 2025.", "source_name": "Splunk RedLine Stealer June 2023", "url": "https://www.splunk.com/en_us/blog/security/do-not-cross-the-redline-stealer-detections-and-analysis.html"}], "id": "relationship--c398b815-5ec1-45a9-bbe8-14153ae5d703", "modified": "2026-04-29T14:23:06.192Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8c8e8b01-b4b1-479b-a7a9-78c40a12b916", "spec_version": "2.1", "target_ref": "attack-pattern--82caa33e-d11a-433a-94ea-9b5a5fbef81d", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19100', 0, 91, '09-mitre-attack', 'retrieved', 'A8F4EB61D5CEFB32E7DAB6C51F88E36D04F72DA419056703E9816DEE8F753AE4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
