VALUES ('doc-09-mitre-attack-p0-19105', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-08T20:55:28.749Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[VBShower](https://attack.mitre.org/software/S0442) has attempted to complicate forensic analysis by deleting all the files contained in %APPDATA%\\..\\Local\\Temporary Internet Files\\Content.Word and %APPDATA%\\..\\Local Settings\\Temporary Internet Files\\Content.Word\\ .(Citation: Kaspersky Cloud Atlas August 2019)", "external_references": [{"description": "GReAT. (2019, August 12). Recent Cloud Atlas activity. Retrieved May 8, 2020.", "source_name": "Kaspersky Cloud Atlas August 2019", "url": "https://securelist.com/recent-cloud-atlas-activity/92016/"}], "id": "relationship--83384e31-d9c6-46a0-956f-ee28d7d0cb89", "modified": "2026-04-29T14:23:06.105Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8caa18af-4758-4fd3-9600-e8af579e89ed", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19105', 0, 79, '09-mitre-attack', 'retrieved', '6408413EE33003F33780F9AB270EBC93547DE3B90756623361342B91DCE66346', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
