VALUES ('doc-09-mitre-attack-p0-19106', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-08T20:55:28.743Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[VBShower](https://attack.mitre.org/software/S0442) used HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Run\\\\[a-f0-9A-F]{8} to maintain persistence.(Citation: Kaspersky Cloud Atlas August 2019)", "external_references": [{"description": "GReAT. (2019, August 12). Recent Cloud Atlas activity. Retrieved May 8, 2020.", "source_name": "Kaspersky Cloud Atlas August 2019", "url": "https://securelist.com/recent-cloud-atlas-activity/92016/"}], "id": "relationship--9cf55e84-53d2-4ec9-aaed-1df38ea08af1", "modified": "2026-04-29T14:23:06.139Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8caa18af-4758-4fd3-9600-e8af579e89ed", "spec_version": "2.1", "target_ref": "attack-pattern--9efb1ea7-c37b-4595-9640-b7680cd84279", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19106', 0, 62, '09-mitre-attack', 'retrieved', '653D3F7B6433D51D485EFAA9923F277F6D8A827CAEB6FC4466C09FAF8ACAD042', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
