VALUES ('doc-09-mitre-attack-p0-19109', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-23T17:26:32.568Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BPFDoor](https://attack.mitre.org/software/S1161) clears the file location `/proc/ /environ` removing all environment variables for the process.(Citation: Sandfly BPFDoor 2022) ", "external_references": [{"description": "The Sandfly Security Team. (2022, May 11). BPFDoor - An Evasive Linux Backdoor Technical Analysis. Retrieved September 29, 2023.", "source_name": "Sandfly BPFDoor 2022", "url": "https://sandflysecurity.com/blog/bpfdoor-an-evasive-linux-backdoor-technical-analysis/"}], "id": "relationship--0d76add8-c0f1-44e3-abf2-f6063c43a100", "modified": "2026-04-29T14:23:05.921Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8d1f89fd-4dde-40ab-80e0-a7b80249162e", "spec_version": "2.1", "target_ref": "attack-pattern--799ace7f-e227-4411-baa0-8868704f2a69", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19109', 0, 74, '09-mitre-attack', 'retrieved', 'EED72ACB9B4B93068F02706CFB772ACD5408B5C3080C09683E35B96E28A4FD0B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
