INSERT INTO knowledge_chunks (id, document_id, section, page, text, embedding_id, authority_tier, token_count, source_id, version, content_hash, processing_version, metadata)
VALUES ('doc-09-mitre-attack-p0-19110', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-03T18:03:04.506Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "When executed, [BPFDoor](https://attack.mitre.org/software/S1161) attempts to create and lock a runtime file, `/var/run/initd.lock`, and exits if it fails using the specified file, resulting in a makeshift mutex.(Citation: Deep Instinct BPFDoor 2023)", "external_references": [{"description": "Shaul Vilkomir-Preisman and Eliran Nissan. (2023, May 10). BPFDoor Malware Evolves – Stealthy Sniffing Backdoor Ups Its Game. Retrieved September 19, 2024.", "source_name": "Deep Instinct BPFDoor 2023", "url": "https://www.deepinstinct.com/blog/bpfdoor-malware-evolves-stealthy-sniffing-backdoor-ups-its-game"}], "id": "relationship--19ac2479-ffef-40dc-9dbb-02c11ba49908", "modified": "2026-04-29T14:23:05.940Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8d1f89fd-4dde-40ab-80e0-a7b80249162e", "spec_version": "2.1", "target_ref": "attack-pattern--49fca0d2-685d-41eb-8bd4-05451cc3a742", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19110', 0, 90, '09-mitre-attack', 'retrieved', '8DFA482E790D18C2927EAF56D126D5DA855F05A41FF96CEFFE64CE1944CCC597', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
