VALUES ('doc-09-mitre-attack-p0-19116', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-23T16:43:02.138Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "After initial setup, [BPFDoor](https://attack.mitre.org/software/S1161)''s original execution process deletes the dropped binary and exits.(Citation: Sandfly BPFDoor 2022) ", "external_references": [{"description": "The Sandfly Security Team. (2022, May 11). BPFDoor - An Evasive Linux Backdoor Technical Analysis. Retrieved September 29, 2023.", "source_name": "Sandfly BPFDoor 2022", "url": "https://sandflysecurity.com/blog/bpfdoor-an-evasive-linux-backdoor-technical-analysis/"}], "id": "relationship--9695560f-3cb5-4138-b52a-9ece83f8f778", "modified": "2026-04-29T14:23:06.130Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8d1f89fd-4dde-40ab-80e0-a7b80249162e", "spec_version": "2.1", "target_ref": "attack-pattern--d63a3fb8-9452-4e9d-a60a-54be68d5998c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19116', 0, 73, '09-mitre-attack', 'retrieved', '37B8D86D09B2484B3CF1F3A1FB9475F69FC5CA9CAE9BBDEFAE6A35031DC0D497', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
