VALUES ('doc-09-mitre-attack-p0-19120', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-23T17:47:14.418Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BPFDoor](https://attack.mitre.org/software/S1161) can require a password to activate the backdoor and uses RC4 encryption or static library encryption `libtomcrypt`.(Citation: Sandfly BPFDoor 2022)", "external_references": [{"description": "The Sandfly Security Team. (2022, May 11). BPFDoor - An Evasive Linux Backdoor Technical Analysis. Retrieved September 29, 2023.", "source_name": "Sandfly BPFDoor 2022", "url": "https://sandflysecurity.com/blog/bpfdoor-an-evasive-linux-backdoor-technical-analysis/"}], "id": "relationship--bc1c0019-3072-413f-add4-da266e467edf", "modified": "2026-04-29T14:23:06.182Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8d1f89fd-4dde-40ab-80e0-a7b80249162e", "spec_version": "2.1", "target_ref": "attack-pattern--b3d682b6-98f2-4fb0-aa3b-b4df007ca70a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19120', 0, 77, '09-mitre-attack', 'retrieved', '860B754394EE0EB5B5ABB600B56EB2A0B5DFF702F44236AE345D8C8860D5FC18', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
