VALUES ('doc-09-mitre-attack-p0-19124', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-10T21:32:58.530Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [Black Basta](https://attack.mitre.org/software/S1070) dropper has been digitally signed with a certificate issued by Akeo Consulting for legitimate executables used for creating bootable USB drives.(Citation: Check Point Black Basta October 2022)", "external_references": [{"description": "Check Point. (2022, October 20). BLACK BASTA AND THE UNNOTICED DELIVERY. Retrieved March 8, 2023.", "source_name": "Check Point Black Basta October 2022", "url": "https://research.checkpoint.com/2022/black-basta-and-the-unnoticed-delivery/"}], "id": "relationship--26e2d87c-43c2-4552-9186-2ca0f70e96c7", "modified": "2026-04-29T14:23:05.958Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8d242fb4-9033-4f13-8a88-4b9b4bcd9a53", "spec_version": "2.1", "target_ref": "attack-pattern--32901740-b42c-4fdd-bc02-345b5dc57082", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19124', 0, 85, '09-mitre-attack', 'retrieved', '92C4BC77FEB86DFFC80DF3CBF437803883C03992E4D2ECE8AFA0588016BD5D0E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
