VALUES ('doc-09-mitre-attack-p0-19127', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-04-08T17:01:48.869Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Black Basta](https://attack.mitre.org/software/S1070) can use LDAP queries to connect to AD and iterate over connected workstations.(Citation: Check Point Black Basta October 2022)", "external_references": [{"description": "Check Point. (2022, October 20). BLACK BASTA AND THE UNNOTICED DELIVERY. Retrieved March 8, 2023.", "source_name": "Check Point Black Basta October 2022", "url": "https://research.checkpoint.com/2022/black-basta-and-the-unnoticed-delivery/"}], "id": "relationship--3341a11e-acd1-4cba-a7a9-5bb48aec8bec", "modified": "2026-04-29T14:23:05.986Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8d242fb4-9033-4f13-8a88-4b9b4bcd9a53", "spec_version": "2.1", "target_ref": "attack-pattern--e358d692-23c0-4a31-9eb6-ecc13a8d7735", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19127', 0, 76, '09-mitre-attack', 'retrieved', '19207A7C1ADDA0210A56BB915FF822AC9FC76542F24F62CB3E633F96D8B1FA72', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
