VALUES ('doc-09-mitre-attack-p0-19130', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-08T20:40:34.782Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Black Basta](https://attack.mitre.org/software/S1070) can encrypt files with the ChaCha20 cypher and using a multithreaded process to increase speed.(Citation: Minerva Labs Black Basta May 2022)(Citation: BlackBerry Black Basta May 2022)(Citation: Cyble Black Basta May 2022)(Citation: NCC Group Black Basta June 2022)(Citation: Uptycs Black Basta ESXi June 2022)(Citation: Deep Instinct Black Basta August 2022)(Citation: Palo Alto Networks Black Basta August 2022)(Citation: Trend Micro Black Basta Spotlight September 2022)(Citation: Check Point Black Basta October 2022) [Black Basta](https://attack.mitre.org/software/S1070) has also encrypted files while the victim system is in safe mode, appending `.basta` upon completion.(Citation: Trend Micro Black Basta May 2022) ", "external_references": [{"description": "Ballmer, D. (2022, May 6). Black Basta: Rebrand of Conti or Something New?. Retrieved March 7, 2023.", "source_name": "BlackBerry Black Basta May 2022", "url": "https://blogs.blackberry.com/en/2022/05/black-basta-rebrand-of-conti-or-something-new"}, {"description": "Check Point. (2022, October 20). BLACK BASTA AND THE UNNOTICED DELIVERY. Retrieved March 8, 2023.", "source_name": "Check Point Black Basta October 2022", "url": "https://research.checkpoint.com/2022/black-basta-and-the-unnoticed-delivery/"}, {"description": "Cyble. (2022, May 6). New ransomware variant targeting high-value organizations. Retrieved November 17, 2024.", "source_name": "Cyble Black Basta May 2022", "url": "https://web.archive.org/web/20220506143054/https://blog.cyble.com/2022/05/06/black-basta-ransomware/"}, {"description": "Elsad, A. (2022, August 25). Threat Assessment: Black Basta Ransomware. Retrieved March 8, 2023.", "source_name": "Palo Alto Networks Black Basta August 2022", "url": "https://unit42.paloaltonetworks.com/threat-assessment-black-basta-ransomware"}, {"description": "Gonzalez, I., Chavez I., et al. (2022, May 9). Examining the Black Basta Ransomware’s Infection Routine. Retrieved March 7, 2023.", "source_name": "Trend Micro Black Basta May 2022", "url": "https://www.trendmicro.com/en_us/research/22/e/examining-the-black-basta-ransomwares-infection-routine.html"}, {"description": "Inman, R. and Gurney, P. (2022, June 6). Shining the Light on Black Basta. Retrieved March 8, 2023.", "source_name": "NCC Group Black Basta June 2022", "url": "https://research.nccgroup.com/2022/06/06/shining-the-light-on-black-basta/"}, {"description": "Sharma, S. and Hegde, N. (2022, June 7). Black basta Ransomware Goes Cross-Platform, Now Targets ESXi Systems. Retrieved March 8, 2023.", "source_name": "Uptycs Black Basta ESXi June 2022", "url": "https://www.uptycs.com/blog/black-basta-ransomware-goes-cross-platform-now-targets-esxi-systems"}, {"description": "Trend Micro. (2022, September 1). Ransomware Spotlight Black Basta. Retrieved March 8, 2023.", "source_name": "Trend Micro Black Basta Spotlight September 2022", "url": "https://www.trendmicro.com/vinfo/us/security/news/ransomware-spotlight/ransomware-spotlight-blackbasta"}, {"description": "Vilkomir-Preisman, S. (2022, August 18). Beating Black Basta Ransomware. Retrieved March 8, 2023.", "source_name": "Deep Instinct Black Basta August 2022", "url": "https://www.deepinstinct.com/blog/black-basta-ransomware-threat-emergence"}, {"description": "Zargarov, N. (2022, May 2). New Black Basta Ransomware Hijacks Windows Fax Service. Retrieved March 7, 2023.", "source_name": "Minerva Labs Black Basta May 2022", "url": "https://minerva-labs.com/blog/new-black-basta-ransomware-hijacks-windows-fax-service/"}], "id": "relationship--6aedddc0-0c82-48f0-b9cc-071d440a367c", "modified": "2026-04-29T14:23:06.071Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8d242fb4-9033-4f13-8a88-4b9b4bcd9a53", "spec_version": "2.1", "target_ref": "attack-pattern--b80d107d-fa0d-4b60-9684-b0433e8bdba0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19130', 0, 388, '09-mitre-attack', 'retrieved', '600BFE5E2BDB5917906315A57CCF90E9B1FC1A177E95A2B7F195812A7D2A88AB', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
