VALUES ('doc-09-mitre-attack-p0-19131', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-03-13T20:18:35.160Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [Black Basta](https://attack.mitre.org/software/S1070) dropper can check system flags, CPU registers, CPU instructions, process timing, system libraries, and APIs to determine if a debugger is present.(Citation: Check Point Black Basta October 2022)", "external_references": [{"description": "Check Point. (2022, October 20). BLACK BASTA AND THE UNNOTICED DELIVERY. Retrieved March 8, 2023.", "source_name": "Check Point Black Basta October 2022", "url": "https://research.checkpoint.com/2022/black-basta-and-the-unnoticed-delivery/"}], "id": "relationship--6bc08584-0dc8-494f-967f-50adc9464843", "modified": "2026-04-29T14:23:06.072Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8d242fb4-9033-4f13-8a88-4b9b4bcd9a53", "spec_version": "2.1", "target_ref": "attack-pattern--e4dc8c01-417f-458d-9ee0-bb0617c1b391", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19131', 0, 86, '09-mitre-attack', 'retrieved', 'EE8BE1F22E6703A331C2B2852095E89AF1325572B4F91D1C3A7788880C0DDE4C', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
