VALUES ('doc-09-mitre-attack-p0-19179', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-19T14:09:25.435Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OopsIE](https://attack.mitre.org/software/S0264) performs several anti-VM and sandbox checks on the victim''s machine. One technique the group has used was to perform a WMI query SELECT * FROM MSAcpi_ThermalZoneTemperature to check the temperature to see if it’s running in a virtual environment.(Citation: Unit 42 OilRig Sept 2018)", "external_references": [{"description": "Falcone, R., et al. (2018, September 04). OilRig Targets a Middle Eastern Government and Adds Evasion Techniques to OopsIE. Retrieved September 24, 2018.", "source_name": "Unit 42 OilRig Sept 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/09/unit42-oilrig-targets-middle-eastern-government-adds-evasion-techniques-oopsie/"}], "id": "relationship--6a93c25c-c9cb-4cd9-a36b-1f2353e91e32", "modified": "2026-04-29T14:23:06.070Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8e101fdd-9f7f-4916-bb04-6bd9e94c129c", "spec_version": "2.1", "target_ref": "attack-pattern--29be378d-262d-4e99-b00d-852d573628e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19179', 0, 107, '09-mitre-attack', 'retrieved', '46FE2F92769E273864F26DE1D952FC443ADC3EEAD99344DF7D8EC040B2EA1F56', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
