VALUES ('doc-09-mitre-attack-p0-19188', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[OopsIE](https://attack.mitre.org/software/S0264) checks to see if the system is configured with \"Daylight\" time and checks for a specific region to be set for the timezone.(Citation: Unit 42 OilRig Sept 2018)", "external_references": [{"description": "Falcone, R., et al. (2018, September 04). OilRig Targets a Middle Eastern Government and Adds Evasion Techniques to OopsIE. Retrieved September 24, 2018.", "source_name": "Unit 42 OilRig Sept 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/09/unit42-oilrig-targets-middle-eastern-government-adds-evasion-techniques-oopsie/"}], "id": "relationship--db4fbefd-e9ed-495a-89af-67c4b6780508", "modified": "2026-04-29T14:23:06.225Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8e101fdd-9f7f-4916-bb04-6bd9e94c129c", "spec_version": "2.1", "target_ref": "attack-pattern--f3c544dc-673c-4ef3-accb-53229f1ae077", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19188', 0, 91, '09-mitre-attack', 'retrieved', '9904F22728CE45AA04AF5566756621C274BF1FDF28E6C91341B054AE6E9DA625', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
