VALUES ('doc-09-mitre-attack-p0-19211', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RogueRobin](https://attack.mitre.org/software/S0270) uses a command prompt to run a PowerShell script from Excel.(Citation: Unit 42 DarkHydrus July 2018) To assist in establishing persistence, [RogueRobin](https://attack.mitre.org/software/S0270) creates %APPDATA%\\OneDrive.bat and saves the following string to it: powershell.exe -WindowStyle Hidden -exec bypass -File “%APPDATA%\\OneDrive.ps1” .(Citation: Unit42 DarkHydrus Jan 2019)(Citation: Unit 42 DarkHydrus July 2018)", "external_references": [{"description": "Falcone, R., et al. (2018, July 27). New Threat Actor Group DarkHydrus Targets Middle East Government. Retrieved August 2, 2018.", "source_name": "Unit 42 DarkHydrus July 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/07/unit42-new-threat-actor-group-darkhydrus-targets-middle-east-government/"}, {"description": "Lee, B., Falcone, R. (2019, January 18). DarkHydrus delivers new Trojan that can use Google Drive for C2 communications. Retrieved April 17, 2019.", "source_name": "Unit42 DarkHydrus Jan 2019", "url": "https://unit42.paloaltonetworks.com/darkhydrus-delivers-new-trojan-that-can-use-google-drive-for-c2-communications/"}, {"description": "Falcone, R., et al. (2018, July 27). New Threat Actor Group DarkHydrus Targets Middle East Government. Retrieved August 2, 2018.", "source_name": "Unit 42 DarkHydrus July 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/07/unit42-new-threat-actor-group-darkhydrus-targets-middle-east-government/"}], "id": "relationship--e58abef6-2089-4f55-b5ee-9fc24378b52f", "modified": "2026-04-29T14:23:06.238Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8ec6e3b4-b06d-4805-b6aa-af916acc2122", "spec_version": "2.1", "target_ref": "attack-pattern--970a3432-3237-47ad-bcca-7d8cbb217736", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19211', 0, 168, '09-mitre-attack', 'retrieved', 'AB4663C90E75CB22127FD8C7A54325D7903991B9058A9B7ABB1FC1C89AB812B6', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
