VALUES ('doc-09-mitre-attack-p0-19217', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-06T21:01:23.245Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Attor](https://attack.mitre.org/software/S0438) can obtain application window titles and then determines which windows to perform Screen Capture on.(Citation: ESET Attor Oct 2019)", "external_references": [{"description": "Hromcova, Z. (2019, October). AT COMMANDS, TOR-BASED COMMUNICATIONS: MEET ATTOR, A FANTASY CREATURE AND ALSO A SPY PLATFORM. Retrieved May 6, 2020.", "source_name": "ESET Attor Oct 2019", "url": "https://www.welivesecurity.com/wp-content/uploads/2019/10/ESET_Attor.pdf"}], "id": "relationship--0dfdfffc-2d1b-487f-91e0-66d81b185367", "modified": "2026-04-29T14:23:05.922Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8f423bd7-6ca7-4303-9e85-008c7ad5fdaa", "spec_version": "2.1", "target_ref": "attack-pattern--4ae4f953-fe58-4cc8-a327-33257e30a830", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19217', 0, 80, '09-mitre-attack', 'retrieved', '14F32995BC84D1CA73DCD7C14FB9F902D9CC0BA5B2AD7301658B152FBCDEF3FF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
