VALUES ('doc-09-mitre-attack-p0-19218', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-06T21:01:23.447Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Attor](https://attack.mitre.org/software/S0438) has encrypted data symmetrically using a randomly generated Blowfish (OFB) key which is encrypted with a public RSA key.(Citation: ESET Attor Oct 2019)", "external_references": [{"description": "Hromcova, Z. (2019, October). AT COMMANDS, TOR-BASED COMMUNICATIONS: MEET ATTOR, A FANTASY CREATURE AND ALSO A SPY PLATFORM. Retrieved May 6, 2020.", "source_name": "ESET Attor Oct 2019", "url": "https://www.welivesecurity.com/wp-content/uploads/2019/10/ESET_Attor.pdf"}], "id": "relationship--1e3a1ea2-55fb-4abc-970a-e384b4c7d314", "modified": "2026-04-29T14:23:05.946Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8f423bd7-6ca7-4303-9e85-008c7ad5fdaa", "spec_version": "2.1", "target_ref": "attack-pattern--24bfaeba-cb0d-4525-b3dc-507c77ecec41", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19218', 0, 84, '09-mitre-attack', 'retrieved', '410BEC1218FC9AC899D8C9F1494770ABB25C42986AC2D85E334D17C430B58880', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
