VALUES ('doc-09-mitre-attack-p0-19219', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-06T21:01:23.653Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Attor](https://attack.mitre.org/software/S0438)''s dispatcher disguises itself as a legitimate task (i.e., the task name and description appear legitimate).(Citation: ESET Attor Oct 2019)", "external_references": [{"description": "Hromcova, Z. (2019, October). AT COMMANDS, TOR-BASED COMMUNICATIONS: MEET ATTOR, A FANTASY CREATURE AND ALSO A SPY PLATFORM. Retrieved May 6, 2020.", "source_name": "ESET Attor Oct 2019", "url": "https://www.welivesecurity.com/wp-content/uploads/2019/10/ESET_Attor.pdf"}], "id": "relationship--20ac9204-3ee3-454d-9d53-d5caa9ec582e", "modified": "2026-04-29T14:23:05.949Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--8f423bd7-6ca7-4303-9e85-008c7ad5fdaa", "spec_version": "2.1", "target_ref": "attack-pattern--7bdca9d5-d500-4d7d-8c52-5fd47baf4c0c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19219', 0, 80, '09-mitre-attack', 'retrieved', 'F0762EFCEC25DA4D04E18E7DD254687C311B4F05437FB12F8EB70C1CD0E9086B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
