VALUES ('doc-09-mitre-attack-p0-19318', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2023-09-27T19:49:53.825Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[NightClub](https://attack.mitre.org/software/S1090) can modify the Creation, Access, and Write timestamps for malicious DLLs to match those of the genuine Windows DLL user32.dll.(Citation: MoustachedBouncer ESET August 2023)", "external_references": [{"description": "Faou, M. (2023, August 10). MoustachedBouncer: Espionage against foreign diplomats in Belarus. Retrieved September 25, 2023.", "source_name": "MoustachedBouncer ESET August 2023", "url": "https://www.welivesecurity.com/en/eset-research/moustachedbouncer-espionage-against-foreign-diplomats-in-belarus/"}], "id": "relationship--51eb8d9b-1ca4-4a9e-9df4-9415e54e8aff", "modified": "2026-04-29T14:23:06.037Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--91c57ed3-7c32-4c68-b388-7db00cb8dac6", "spec_version": "2.1", "target_ref": "attack-pattern--47f2d673-ca62-47e9-929b-1b0be9657611", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19318', 0, 79, '09-mitre-attack', 'retrieved', '1ADA3E7769A3359C02CA8C46F3280F7CCE186B4BE6EE023BF91C624CB40FE383', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
