VALUES ('doc-09-mitre-attack-p0-19348', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-09T18:57:46.007Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Akira _v2](https://attack.mitre.org/software/S1194) can enumerate the trace, debug, error, info, and warning logs on targeted systems.(Citation: Cisco Akira Ransomware OCT 2024)(Citation: Palo Alto Howling Scorpius DEC 2024)", "external_references": [{"description": "Nutland, J. and Szeliga, M. (2024, October 21). Akira ransomware continues to evolve. Retrieved December 10, 2024.", "source_name": "Cisco Akira Ransomware OCT 2024", "url": "https://blog.talosintelligence.com/akira-ransomware-continues-to-evolve/"}, {"description": "Zemah, Y. (2024, December 2). Threat Assessment: Howling Scorpius (Akira Ransomware). Retrieved January 8, 2025.", "source_name": "Palo Alto Howling Scorpius DEC 2024", "url": "https://unit42.paloaltonetworks.com/threat-assessment-howling-scorpius-akira-ransomware/"}], "id": "relationship--9c0b8bff-6cfe-4b12-843c-19985efd2d3b", "modified": "2026-04-29T14:23:06.138Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--929d0d4d-b7c6-4ee8-81eb-43c849294e27", "spec_version": "2.1", "target_ref": "attack-pattern--866d0d6d-02c6-42bd-aa2f-02907fdc0969", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19348', 0, 107, '09-mitre-attack', 'retrieved', '0F6748D13DDFD86CCAB629BEDD1E619E718E54C45CC6F60B41744DC0E82112BF', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
