VALUES ('doc-09-mitre-attack-p0-19349', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-09T18:55:25.582Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "The [Akira _v2](https://attack.mitre.org/software/S1194) encryptor targets the `/vmfs/volumes/` path by default and can use the rust-crypto 0.2.36 library crate for the encryption processes.(Citation: Cisco Akira Ransomware OCT 2024)(Citation: Palo Alto Howling Scorpius DEC 2024)", "external_references": [{"description": "Nutland, J. and Szeliga, M. (2024, October 21). Akira ransomware continues to evolve. Retrieved December 10, 2024.", "source_name": "Cisco Akira Ransomware OCT 2024", "url": "https://blog.talosintelligence.com/akira-ransomware-continues-to-evolve/"}, {"description": "Zemah, Y. (2024, December 2). Threat Assessment: Howling Scorpius (Akira Ransomware). Retrieved January 8, 2025.", "source_name": "Palo Alto Howling Scorpius DEC 2024", "url": "https://unit42.paloaltonetworks.com/threat-assessment-howling-scorpius-akira-ransomware/"}], "id": "relationship--b5ae6046-3a14-4cae-8612-c9d414567e19", "modified": "2026-04-29T14:23:06.173Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--929d0d4d-b7c6-4ee8-81eb-43c849294e27", "spec_version": "2.1", "target_ref": "attack-pattern--b80d107d-fa0d-4b60-9684-b0433e8bdba0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19349', 0, 114, '09-mitre-attack', 'retrieved', 'DBD96C97218132E5D3D6344BDB497D28F87B4BAE1343459798D6D0AE2EA49099', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
