VALUES ('doc-09-mitre-attack-p0-19399', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-06-16T15:37:50.908Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[RTM](https://attack.mitre.org/software/S0148) has resolved [Pony](https://attack.mitre.org/software/S0453) C2 server IP addresses by either converting Bitcoin blockchain transaction data to specific octets, or accessing IP addresses directly within the Namecoin blockchain.(Citation: CheckPoint Redaman October 2019)(Citation: Unit42 Redaman January 2019)", "external_references": [{"description": "Eisenkraft, K., Olshtein, A. (2019, October 17). Pony’s C&C servers hidden inside the Bitcoin blockchain. Retrieved June 15, 2020.", "source_name": "CheckPoint Redaman October 2019", "url": "https://research.checkpoint.com/2019/ponys-cc-servers-hidden-inside-the-bitcoin-blockchain/"}, {"description": "Duncan, B., Harbison, M. (2019, January 23). Russian Language Malspam Pushing Redaman Banking Malware. Retrieved June 16, 2020.", "source_name": "Unit42 Redaman January 2019", "url": "https://unit42.paloaltonetworks.com/russian-language-malspam-pushing-redaman-banking-malware/"}], "id": "relationship--25eb9cd3-80e1-4116-bfd3-fa3819dc2079", "modified": "2026-04-29T14:23:05.957Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "malware--92ec0cbd-2c30-44a2-b270-73f4ec949841", "spec_version": "2.1", "target_ref": "attack-pattern--7bd9c723-2f78-4309-82c5-47cad406572b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-19399', 0, 118, '09-mitre-attack', 'retrieved', 'E3C1FEF544EF5B7699B9A5F66F6D6D870FF53078ED0084F0303124D14C9D0F03', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_obje